def codex_instant(value, allow_date=False):
    text = str(value or "")
    stamp = datetime.fromisoformat(text[:-1] + "+00:00" if text.endswith("Z") else text)
    if stamp.tzinfo is None:
        if not allow_date or len(text) != 10:
