def codex_billing_context(profiles, user, at, recorded_auth, config_auth=""):
    """Resolve billing identity, preferring the strongest evidence available.

    recorded (the session said so) > profile (operator declared it) > config (present
    account state, projected) > unknown. The source is returned so a consumer can tell
    a projection from a record rather than having to trust the label.
    """
    recorded = {"chatgpt": "chatgpt", "api": "api", "api_key": "api"}.get(
        str(recorded_auth or "").lower(), ""
    )
    try:
        instant = codex_instant(at, allow_date=True)
    except (TypeError, ValueError):
        return recorded or "unknown", "", "invalid timestamp"
    matches = [entry for entry in profiles.get(user, ())
               if codex_instant(entry.get("from")) <= instant
               < codex_instant(entry.get("until"))]
    if len(matches) > 1:
        raise ValueError(f"overlapping Codex billing profiles for {user!r} at {at}")
    profile = matches[0] if matches else None
    if recorded:
        if profile and profile.get("billing_system") != recorded:
            return recorded, "", "recorded/profile conflict"
        return recorded, (profile or {}).get("rate_profile", ""), "recorded"
    if profile:
        return profile.get("billing_system", "unknown"), \
            profile.get("rate_profile", ""), "profile"
    if config_auth:
        return config_auth, "", "config"
    return "unknown", "", "no profile"


def load_codex_profiles(path="billing_profiles.local.json"):
    if not path or not os.path.exists(path):
        return {}
    with open(path, encoding="utf-8") as fh:
        data = json.load(fh)
    users = data.get("users") if isinstance(data, dict) else None
    if not isinstance(data, dict) or data.get("version") != 1 or not isinstance(users, dict):
        raise ValueError("Codex billing profiles require version 1 and a users object")
    for user, entries in users.items():
        if not isinstance(entries, list):
            raise ValueError(f"Codex billing profile {user!r} must be a list")
        ranges = []
        for entry in entries:
            if (entry.get("billing_system") not in ("chatgpt", "api")
                    or not entry.get("rate_profile")):
                raise ValueError(f"invalid Codex billing profile for {user!r}")
            try:
                start, end = codex_instant(entry.get("from")), codex_instant(entry.get("until"))
            except (TypeError, ValueError):
                raise ValueError(f"invalid Codex billing profile for {user!r}") from None
            if start >= end:
                raise ValueError(f"invalid Codex billing profile for {user!r}")
            ranges.append((start, end))
        ranges.sort()
        for index, (start, end) in enumerate(ranges):
            if index and ranges[index - 1][1] > start:
                raise ValueError(f"overlapping Codex billing profiles for {user!r}")
    return users

